<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useWorkspaceStore } from '../core/store.ts';
import { entryKind, type PresetPrompt } from '../types.ts';

const props = defineProps<{
  展开: boolean;
  /** 打开时落在哪个页签 */
  初始页签: 页签;
}>();

const emit = defineEmits<{
  /** 注入这些条目（键为 `${presetId}::${promptId}`）；已进目标的只标记，没进目标的会先逐条加进目标 */
  注入: [条目: { 预设id: string; promptId: string }[]];
  /** 取消这些条目的注入（键同上） */
  取消注入: [键: string[]];
  关闭: [];
}>();

type 页签 = '已注入' | '目标条目' | '源预设';

const store = useWorkspaceStore();
const 当前页签 = ref<页签>(props.初始页签);
const 勾选 = ref<Set<string>>(new Set());
/** 源预设页签里当前看的是哪个导入预设 */
const 当前预设id = ref<string | null>(null);

watch(
  () => props.展开,
  open => {
    if (!open) return;
    当前页签.value = props.初始页签;
    勾选.value = new Set();
  },
  { immediate: true },
);

// 每次换页签清空勾选：两个页签的语义不同（一个要注入、一个要取消），
// 留着勾选会让用户以为「我刚勾的是要注入的」，实际点下去却是取消
watch(当前页签, () => {
  勾选.value = new Set();
});

/** 被取消注入的 uid。空集 = 目标栏全部注入 */
const 排除集 = computed(() => new Set(store.workspace.ai.injectionExcluded));
const 目标 = computed(() => store.slot.prompts);

/** 第 1 页：目前注入的，也就是目标栏里没被排除的 */
const 已注入列表 = computed(() => 目标.value.filter(t => !排除集.value.has(t._uid)));

/** 第 3 页：当前选中源预设里的全部条目 */
const 源预设条目 = computed(() => {
  const 预设 = store.workspace.imports.find(i => i.id === 当前预设id.value);
  return 预设 ? store.条目(预设).map(p => ({ 预设, prompt: p })) : [];
});

const 目标键 = computed(() => new Set(目标.value.map(t => t._uid)));

function 键(presetId: string, promptId: string) {
  return `${presetId}::${promptId}`;
}

function 切换(键值: string) {
  const 下一个 = new Set(勾选.value);
  下一个.has(键值) ? 下一个.delete(键值) : 下一个.add(键值);
  勾选.value = 下一个;
}

/** 当前页签里所有可勾的键 */
const 当前全部键 = computed<string[]>(() => {
  if (当前页签.value === '已注入') return 已注入列表.value.map(t => t._uid);
  if (当前页签.value === '目标条目') return 目标.value.map(t => t._uid);
  return 源预设条目.value.map(x => 键(x.预设.id, x.prompt.id));
});

function 全选() {
  勾选.value = 勾选.value.size ? new Set() : new Set(当前全部键.value);
}

/** 把勾选的键拆回 { 预设id, promptId } */
function 拆键(键列表: string[]) {
  return 键列表.map(k => {
    const [预设id, ...余] = k.split('::');
    return { 预设id, promptId: 余.join('::') };
  });
}

/**
 * 两个动作都常驻在底部，不按页签切换。
 *
 * 因为默认是「全部注入」，用户既可能想把某些条排除掉，也可能想把排除掉的加回来，
 * 两种意图在同一个页签里都会出现，做成一个会变的按钮反而要多想一步。
 */
function 执行注入选中() {
  if (勾选.value.size === 0) return;
  emit('注入', 拆键([...勾选.value]));
  勾选.value = new Set();
}

function 执行取消选中() {
  if (勾选.value.size === 0) return;
  emit('取消注入', [...勾选.value]);
  勾选.value = new Set();
}

function 徽章(p: PresetPrompt): string {
  const k = entryKind(p);
  return k === 'system' ? '系统' : k === 'placeholder' ? '占位' : '';
}
</script>

<template>
  <div v-if="展开" class="fixed inset-0 z-50 flex items-center justify-center p-4" @click.self="emit('关闭')">
    <div class="absolute inset-0 bg-black/50" />

    <div class="relative glass-strong rounded-xl w-full max-w-3xl h-[80vh] flex flex-col overflow-hidden">
      <!-- 顶部：三个切换 -->
      <div class="px-3 py-2 shrink-0 border-b border-line flex items-center gap-2 text-xs">
        <i class="fa-solid fa-syringe text-accent" />
        <span class="font-medium shrink-0">注入条目</span>
        <div class="flex gap-1 ml-2">
          <button
            v-for="页 in [
              { key: '已注入' as const, 名: '目前注入条目' },
              { key: '目标条目' as const, 名: '目标条目' },
              { key: '源预设' as const, 名: '源预设' },
            ]"
            :key="页.key"
            class="px-2 py-0.5 rounded border transition-colors whitespace-nowrap"
            :class="
              当前页签 === 页.key
                ? 'border-accent bg-accent-soft/40 text-accent font-medium'
                : 'border-line hover:border-line-strong'
            "
            @click="当前页签 = 页.key"
          >
            {{ 页.名 }}
            <span v-if="页.key === '已注入'" class="opacity-70">{{ 已注入列表.length }}</span>
          </button>
        </div>
        <button class="ml-auto text-muted hover:text-danger shrink-0" @click="emit('关闭')">
          <i class="fa-solid fa-xmark" />
        </button>
      </div>

      <!-- 源预设页签：选哪个导入预设 -->
      <div v-if="当前页签 === '源预设'" class="px-3 py-1.5 shrink-0 border-b border-line/60 flex items-center gap-2 text-[11px]">
        <span class="text-muted shrink-0">选择预设</span>
        <select v-model="当前预设id" class="flex-1 max-w-96 text-xs py-0.5">
          <option :value="null">（请选择）</option>
          <option v-for="i in store.workspace.imports" :key="i.id" :value="i.id">{{ i.name }}</option>
        </select>
        <span v-if="当前预设id" class="text-muted">
          {{ 源预设条目.length }} 条 · 已进目标 {{ 源预设条目.filter(x => 目标键.has(键(x.预设.id, x.prompt.id))).length }} 条
        </span>
      </div>

      <!-- 提示条 -->
      <div class="px-3 py-1.5 shrink-0 border-b border-line/60 flex items-center gap-2 text-[10px] text-muted">
        <template v-if="当前页签 === '已注入'">
          目标栏的条目<span class="text-accent">默认全部注入</span>。勾几条点「取消注入」，它们就不再作为 AI 的固定参照，但<span class="text-accent">仍留在新预设里</span>。
        </template>
        <template v-else-if="当前页签 === '目标条目'">
          这里列出目标栏全部条目，后面的小字标明它现在注没注入。
        </template>
        <template v-else>
          勾选后点「注入」：来自源预设的条目会<span class="text-warn">先逐条加进目标预设</span>，再作为 AI 的固定参照。
        </template>
        <button class="ml-auto shrink-0 hover:text-accent" @click="全选">
          {{ 勾选.size ? '全不选' : '全选' }}
        </button>
      </div>

      <!-- 列表 -->
      <div class="flex-1 min-h-0 overflow-y-auto">
        <!-- 1. 目前注入的 -->
        <template v-if="当前页签 === '已注入'">
          <div v-if="已注入列表.length === 0" class="p-4 text-xs text-muted">还没有注入任何条目。</div>
          <label
            v-for="t in 已注入列表"
            :key="t._uid"
            class="flex items-center gap-2 px-3 py-1 text-xs hover:bg-surface2/60 cursor-pointer border-b border-line/40"
          >
            <input type="checkbox" class="shrink-0" :checked="勾选.has(t._uid)" @change="切换(t._uid)" />
            <i class="fa-solid fa-check text-accent text-[10px] shrink-0" />
            <span class="truncate flex-1">{{ t.name }}</span>
          </label>
        </template>

        <!-- 2. 目标条目 -->
        <template v-else-if="当前页签 === '目标条目'">
          <div v-if="目标.length === 0" class="p-4 text-xs text-muted">目标栏还没有条目。</div>
          <label
            v-for="t in 目标"
            :key="t._uid"
            class="flex items-center gap-2 px-3 py-1 text-xs hover:bg-surface2/60 cursor-pointer border-b border-line/40"
            :class="排除集.has(t._uid) ? '' : 'text-accent'"
          >
            <input type="checkbox" class="shrink-0" :checked="勾选.has(t._uid)" @change="切换(t._uid)" />
            <span class="truncate flex-1">{{ t.name }}</span>
            <span v-if="排除集.has(t._uid)" class="text-[10px] text-muted shrink-0">未注入</span>
            <span v-else class="text-[10px] shrink-0">已注入</span>
          </label>
        </template>

        <!-- 3. 源预设 -->
        <template v-else>
          <div v-if="!当前预设id" class="p-4 text-xs text-muted">先在上面选一个预设。</div>
          <div v-else-if="源预设条目.length === 0" class="p-4 text-xs text-muted">这个预设没有条目。</div>
          <label
            v-for="x in 源预设条目"
            :key="键(x.预设.id, x.prompt.id)"
            class="flex items-center gap-2 px-3 py-1 text-xs hover:bg-surface2/60 cursor-pointer border-b border-line/40"
            :class="目标键.has(键(x.预设.id, x.prompt.id)) ? 'text-muted' : ''"
          >
            <input
              type="checkbox"
              class="shrink-0"
              :checked="勾选.has(键(x.预设.id, x.prompt.id))"
              @change="切换(键(x.预设.id, x.prompt.id))"
            />
            <span v-if="徽章(x.prompt)" class="shrink-0 text-[10px] px-1 rounded bg-surface2 text-muted">
              {{ 徽章(x.prompt) }}
            </span>
            <span class="truncate flex-1">{{ x.prompt.name }}</span>
            <span v-if="目标键.has(键(x.预设.id, x.prompt.id))" class="text-[10px] shrink-0">已在目标</span>
          </label>
        </template>
      </div>

      <!-- 底部 -->
      <div class="px-3 py-2 shrink-0 border-t border-line flex items-center gap-2 flex-wrap">
        <span class="text-[10px] text-muted flex-1 min-w-40">
          已勾选 {{ 勾选.size }} 条 · 目标栏默认全部注入，这里的操作只影响「给不给 AI 看」，不删条目
        </span>
        <button
          class="px-3 py-1 rounded-md bg-accent text-accent-text font-medium text-xs disabled:opacity-40"
          :disabled="勾选.size === 0"
          title="恢复注入（源预设的条目会先逐条加进目标）"
          @click="执行注入选中"
        >
          <i class="fa-solid fa-plus mr-1" />注入（{{ 勾选.size }}）
        </button>
        <button
          class="px-3 py-1 rounded-md border border-line hover:border-danger hover:text-danger text-xs disabled:opacity-40"
          :disabled="勾选.size === 0"
          title="取消注入；目标条目本身不受影响"
          @click="执行取消选中"
        >
          <i class="fa-solid fa-minus mr-1" />取消注入（{{ 勾选.size }}）
        </button>
      </div>
    </div>
  </div>
</template>
