<script setup lang="ts">
/**
 * AI 生成结果列表（待确认区）。
 *
 * 原先是 TargetPromptList 的下半区，抽出来的原因是手机版：
 * 手机屏幕窄，把「AI 助手」和「目标条目」拆成了两个一级页签，
 * 结果列表应该跟着 AI 助手走，而不是埋在目标条目列表下面 ——
 * 否则手机上就成了「源列表 / 目标列表 / 生成结果」三层套娃。
 *
 * 读的是 store.slot.aiResults，与任何组件解耦，
 * 所以抽取对桌面版是纯搬运，外观与行为都不变。
 */
import { computed } from 'vue';
import { useWorkspaceStore } from '../core/store.ts';

const emit = defineEmits<{
  /** 点一条结果 → 进「条目比对」页做前后对照 */
  开始对比: [ids: string[]];
}>();

const store = useWorkspaceStore();

/**
 * 只列还没确认的结果。
 *
 * 已确认的从列表里消失 —— 它的内容已经进了目标条目，
 * 再挂在待办列表里只会让人以为还有事没做完。
 */
const 待确认结果 = computed(() => store.slot.aiResults.filter(r => !r.applied));
</script>

<template>
  <div class="flex-1 min-h-0 flex flex-col">
    <div
      class="px-2 py-1.5 shrink-0 text-[11px] bg-surface2/45 border-b border-line/50 flex items-center gap-1.5"
    >
      <i class="fa-solid fa-wand-magic-sparkles text-accent" />
      <span class="text-accent">AI 生成结果</span>
      <span v-if="待确认结果.length" class="text-warn">待确认 {{ 待确认结果.length }}</span>
      <span class="ml-auto opacity-70 text-muted truncate">点一条进「条目比对」</span>
    </div>

    <div class="flex-1 min-h-0 overflow-y-auto">
      <div v-if="待确认结果.length === 0" class="p-3 text-[11px] text-muted leading-relaxed">
        没有待确认的结果。在 AI 助手里点「对齐润色」或「合并同主题」，
        结果会逐条出现在这里；点开比对、确认之后才会写进目标条目。
      </div>

      <div
        v-for="r in 待确认结果"
        :key="'ai-' + r.id"
        :data-栏="'ai'"
        :data-uid="r.targetUids[0]"
        class="px-2 py-1 border-b border-line/40 cursor-pointer transition-colors hover:bg-surface2/60"
        title="点击进「条目比对」，看新旧对照后再决定采不采用"
        @click="emit('开始对比', [r.id])"
      >
        <div class="flex items-center gap-1.5">
          <span class="truncate flex-1">{{ r.name }}</span>
          <span v-if="r.mode === 'merged'" class="text-[10px] text-warn shrink-0">
            合并 {{ r.targetUids.length }} 条
          </span>
          <span class="text-[10px] text-accent shrink-0">待确认</span>
        </div>
        <div class="text-[10px] truncate text-body">
          {{ (r.content || '').replace(/\s+/g, ' ').slice(0, 90) || '（空）' }}
        </div>
      </div>
    </div>
  </div>
</template>
