<script setup lang="ts">
/**
 * 可拖动的上下分隔线。
 *
 * 两个关键设计，都是踩过坑换来的：
 *
 * 1. 用 Pointer Events + setPointerCapture，不用 mousedown + window.mousemove。
 *    本扩展的代码运行在【酒馆主页面的 JS 作用域】里，裸 window 是酒馆的 window，
 *    在面板 iframe 里拖鼠标事件不会冒泡过去，挂在 window 上的监听永远收不到。
 *    setPointerCapture 把后续事件直接派发给手柄元素本身，完全不需要 window 监听。
 *
 * 2. 父组件务必用 computed 返回样式对象来定高，不要在模板里写模板字符串：
 *    `:style="{ flex: `${比例} 1 0%` }"` 一旦 ref 没被解包就是非法 CSS，
 *    整条声明被丢弃，布局直接塌掉。
 */
const 下限 = 20;
const 上限 = 80;

const emit = defineEmits<{ 拖动: [比例: number] }>();

function 按下(event: PointerEvent) {
  const 手柄 = event.currentTarget as HTMLElement;
  const 容器 = 手柄.parentElement;
  if (!容器) return;

  event.preventDefault();
  手柄.setPointerCapture(event.pointerId);

  const 计算 = (e: PointerEvent) => {
    const 矩形 = 容器.getBoundingClientRect();
    if (矩形.height === 0) return;
    emit('拖动', Math.min(上限, Math.max(下限, ((e.clientY - 矩形.top) / 矩形.height) * 100)));
  };

  const 移动 = (e: PointerEvent) => 计算(e);
  const 松开 = (e: PointerEvent) => {
    try {
      手柄.releasePointerCapture(e.pointerId);
    } catch {
      /* 指针已释放时忽略 */
    }
    手柄.removeEventListener('pointermove', 移动);
    手柄.removeEventListener('pointerup', 松开);
    手柄.removeEventListener('pointercancel', 松开);
  };

  手柄.addEventListener('pointermove', 移动);
  手柄.addEventListener('pointerup', 松开);
  手柄.addEventListener('pointercancel', 松开);
  计算(event);
}
</script>

<template>
  <div
    class="h-2 pointer-coarse:h-5 shrink-0 cursor-row-resize select-none flex items-center justify-center group"
    style="touch-action: none"
    title="按住拖动，调整上下高度"
    @pointerdown="按下"
  >
    <div class="w-14 pointer-coarse:w-20 h-0.5 rounded-full bg-line-strong group-hover:bg-accent transition-colors" />
  </div>
</template>
