import { entryKind, type EntryConflict, type TargetPrompt } from '../types.ts';

/**
 * 检测目标条目之间的冲突。
 *
 * 为什么只警告不阻断：
 * - 同深度挤车在酒馆里是合法的（靠 order 区分先后），但跨预设缝合时 order 值可能撞车，
 *   提示用户但不阻止，因为用户可能就是想让它俩并列。
 * - 重名在酒馆里也合法，只是难辨认。
 *
 * 唯一硬冲突是系统词/占位符 id 重复 —— 那个会被酒馆助手直接抛异常阻断，
 * 但本函数仍只报告，由 UI 在源头阻止这类条目进入目标。
 */
export function detectEntryConflicts(prompts: TargetPrompt[]): EntryConflict[] {
  const conflicts: EntryConflict[] = [];

  // 1. 系统词 / 占位符 id 重复 —— 第二条起算冲突
  const seenSystem = new Set<string>();
  const seenPlaceholder = new Set<string>();
  for (const prompt of prompts) {
    const kind = entryKind(prompt);
    if (kind === 'system') {
      if (seenSystem.has(prompt.id)) {
        conflicts.push({ type: 'duplicate_system', uid: prompt._uid, id: prompt.id });
      } else {
        seenSystem.add(prompt.id);
      }
    } else if (kind === 'placeholder') {
      if (seenPlaceholder.has(prompt.id)) {
        conflicts.push({ type: 'duplicate_placeholder', uid: prompt._uid, id: prompt.id });
      } else {
        seenPlaceholder.add(prompt.id);
      }
    }
  }

  // 2. 同深度挤车
  const byDepth = new Map<number, string[]>();
  for (const prompt of prompts) {
    if (prompt.position?.type !== 'in_chat') continue;
    const list = byDepth.get(prompt.position.depth) ?? [];
    list.push(prompt._uid);
    byDepth.set(prompt.position.depth, list);
  }
  for (const [depth, uids] of byDepth) {
    if (uids.length > 1) conflicts.push({ type: 'same_depth', uids, depth });
  }

  // 3. 重名
  const byName = new Map<string, string[]>();
  for (const prompt of prompts) {
    const list = byName.get(prompt.name) ?? [];
    list.push(prompt._uid);
    byName.set(prompt.name, list);
  }
  for (const [name, uids] of byName) {
    if (uids.length > 1) conflicts.push({ type: 'duplicate_name', uids, name });
  }

  return conflicts;
}

/** 取冲突涉及的全部 uid，供 UI 标黄/标橙 */
export function conflictUids(conflicts: EntryConflict[]): Map<string, string> {
  const map = new Map<string, string>();
  for (const conflict of conflicts) {
    if (conflict.type === 'duplicate_system' || conflict.type === 'duplicate_placeholder') {
      map.set(conflict.uid, 'red');
    } else if (conflict.type === 'same_depth') {
      for (const uid of conflict.uids) if (!map.has(uid)) map.set(uid, 'yellow');
    } else {
      for (const uid of conflict.uids) if (!map.has(uid)) map.set(uid, 'orange');
    }
  }
  return map;
}
