<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useWorkspaceStore } from '../core/store.ts';
import type { TavernRegex } from '../types.ts';

const emit = defineEmits<{ 选中: [regex: TavernRegex] }>();

const store = useWorkspaceStore();
const 批量模式 = ref(false);
const 关键词 = ref('');
const 勾选 = ref<Set<string>>(new Set());

const 来源 = computed(() => store.正则来源);

const 列表 = computed(() => {
  const kw = 关键词.value.trim();
  if (!kw) return 来源.value;
  return 来源.value.filter(
    e => e.regex.script_name.includes(kw) || e.regex.find_regex.includes(kw) || e.presetName.includes(kw),
  );
});

const 可批量 = computed(() => 列表.value.filter(e => !已选中(e.regex.id)));

watch(批量模式, 开 => { if (!开) 勾选.value = new Set(); });

function 已选中(id: string): boolean {
  return store.slot.regexes.some(r => r.id === id);
}

function 范围(r: TavernRegex): string {
  const 部分: string[] = [];
  if (r.source.user_input) 部分.push('用户');
  if (r.source.ai_output) 部分.push('AI');
  if (r.source.slash_command) 部分.push('命令');
  if (r.source.world_info) 部分.push('世界书');
  if (r.source.reasoning) 部分.push('推理');
  return 部分.join('/') || '无范围';
}

function 用途(r: TavernRegex): string {
  const 部分: string[] = [];
  if (r.destination.display) 部分.push('显示');
  if (r.destination.prompt) 部分.push('提示词');
  return 部分.join('/') || '无用途';
}

function 切换勾选(id: string) {
  const 下一个 = new Set(勾选.value);
  下一个.has(id) ? 下一个.delete(id) : 下一个.add(id);
  勾选.value = 下一个;
}

function 全选() {
  勾选.value = 勾选.value.size > 0 ? new Set() : new Set(可批量.value.map(e => e.regex.id));
}

function 批量加入() {
  const 待加 = 来源.value.filter(e => 勾选.value.has(e.regex.id)).map(e => e.regex);
  const 数 = store.批量加入正则(待加);
  勾选.value = new Set();
  toastr.success(数 ? `已批量加入 ${数} 条正则` : '勾选的正则都已在目标中', '奇美拉·预设缝合台');
}

function 点击(regex: TavernRegex) {
  if (批量模式.value) {
    if (!已选中(regex.id)) 切换勾选(regex.id);
    return;
  }
  emit('选中', regex);
}
</script>

<template>
  <div class="flex flex-col flex-1 min-h-0">
    <div class="p-2 space-y-1.5 border-b border-line shrink-0">
      <input v-model="关键词" class="w-full text-xs" placeholder="搜索正则…" />
      <div class="flex items-center gap-2 text-[11px] text-muted">
        <span>共 {{ 来源.length }} 条</span>
        <button
          class="ml-auto px-1.5 py-0.5 rounded border transition-colors"
          :class="批量模式 ? 'border-accent text-accent bg-accent-soft/40' : 'border-line hover:border-line-strong'"
          @click="批量模式 = !批量模式"
        >
          <i class="fa-solid fa-list-check" /> 批量
        </button>
      </div>

      <div v-if="批量模式" class="flex items-center gap-1.5 text-[11px]">
        <button class="px-1.5 py-0.5 rounded border border-line hover:border-accent" @click="全选">
          {{ 勾选.size ? '全不选' : '全选' }}
        </button>
        <button
          class="px-2 py-0.5 rounded bg-accent text-accent-text font-medium disabled:opacity-40"
          :disabled="勾选.size === 0"
          @click="批量加入"
        >
          加入 {{ 勾选.size }} 条
        </button>
      </div>
    </div>

    <div class="flex-1 overflow-y-auto">
      <div v-if="来源.length === 0" class="p-3 text-xs text-muted leading-relaxed">
        导入的预设里没有内嵌正则。
      </div>
      <div v-else-if="列表.length === 0" class="p-3 text-xs text-muted">没有匹配的正则</div>

      <div
        v-for="entry in 列表"
        :key="entry.regex.id"
        class="px-2 py-1 border-b border-line/40 text-xs transition-colors cursor-pointer"
        :class="已选中(entry.regex.id) ? 'text-accent bg-accent-soft/25' : 'hover:bg-surface2/60'"
        @click="点击(entry.regex)"
      >
        <div class="flex items-center gap-1.5">
          <input
            v-if="批量模式"
            type="checkbox"
            class="shrink-0"
            :checked="勾选.has(entry.regex.id)"
            :disabled="已选中(entry.regex.id)"
            @click.stop="切换勾选(entry.regex.id)"
          />
          <span class="truncate flex-1">{{ entry.regex.script_name }}</span>
          <span v-if="!entry.regex.enabled" class="text-[10px] text-muted shrink-0">禁用</span>
          <i v-if="已选中(entry.regex.id)" class="fa-solid fa-check text-accent shrink-0" />
        </div>
        <div class="text-[10px] text-muted truncate">
          {{ entry.presetName }} · {{ 范围(entry.regex) }} · {{ 用途(entry.regex) }}
        </div>
        <div class="text-[10px] text-muted truncate font-mono opacity-70">{{ entry.regex.find_regex }}</div>
      </div>
    </div>
  </div>
</template>
