<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useWorkspaceStore } from '../core/store.ts';
import {
  VARIABLE_CONSOLE_UID,
  entryKind,
  hasPositionField,
  type 编辑对象,
  type PresetPrompt,
} from '../types.ts';

const props = defineProps<{
  /** 当前编辑的对象；null 表示没选任何条目 */
  对象: 编辑对象 | null;
  /**
   * 从变量树点冲突值行时带过来的「要不要采用这个值」。
   *
   * 单独做一个浮条而不是内嵌进编辑表单：编辑器本身是纯粹的编辑界面，
   * 而裁决是变量层的事。浮条只在这一个场景出现，不打扰正常编辑。
   */
  待采用?: { 变量名: string; 值: string } | null;
}>();

const emit = defineEmits<{ 采用值: [] }>();

const store = useWorkspaceStore();

/** 编辑器里的一份草稿。改完点保存才写回去 */
type 草稿 = {
  名称: string;
  内容: string;
  启用: boolean;
  角色: 'system' | 'user' | 'assistant';
  位置?: PresetPrompt['position'];
};

const 草稿 = ref<草稿 | null>(null);
/** 当前对象的说明性元信息（只读展示） */
const 元信息 = ref<{ 类别: string; 来源: string; 可保存: boolean; 提示?: string }>({
  类别: '普通条目',
  来源: '',
  可保存: false,
});

const 对象标识 = computed(() => {
  const o = props.对象;
  if (!o) return '';
  return o.类型 === 'target' ? `target:${o.uid}` : o.类型 === 'ai' ? `ai:${o.id}` : `source:${o.presetId}:${o.promptId}`;
});

/** 把三种来源统一读成一份草稿 */
function 读入(): void {
  const o = props.对象;
  if (!o) {
    草稿.value = null;
    return;
  }

  if (o.类型 === 'target') {
    const 条目 = store.slot.prompts.find(t => t._uid === o.uid);
    if (!条目) {
      草稿.value = null;
      return;
    }
    const 是控制台 = 条目._uid === VARIABLE_CONSOLE_UID;
    元信息.value = {
      类别: 类别名(entryKind(条目)),
      来源: 条目._from ? '缝进来的目标条目' : '手工新建的目标条目',
      可保存: true,
      提示: 是控制台 ? '变量声明条目由「变量」轨自动生成，手改会在下次「应用到目标」时被覆盖' : undefined,
    };
    草稿.value = {
      名称: 条目.name,
      内容: 条目.content ?? '',
      启用: 条目.enabled,
      角色: 条目.role,
      位置: 条目.position,
    };
    return;
  }

  if (o.类型 === 'ai') {
    const 结果 = store.slot.aiResults.find(r => r.id === o.id);
    if (!结果) {
      草稿.value = null;
      return;
    }
    元信息.value = {
      类别: 'AI 生成结果',
      来源: '还没替换进目标，改完只影响这条结果本身',
      可保存: true,
      提示: '这是待替换的 AI 结果，不是目标条目。替换后才进入目标栏。',
    };
    草稿.value = { 名称: 结果.name, 内容: 结果.content, 启用: true, 角色: 'system', 位置: undefined };
    return;
  }

  // source
  const 预设 = store.workspace.imports.find(i => i.id === o.presetId);
  const 条目 = 预设 ? store.条目(预设).find(p => p.id === o.promptId) : undefined;
  if (!预设 || !条目) {
    草稿.value = null;
    return;
  }
  元信息.value = {
    类别: 类别名(entryKind(条目)),
    来源: `源预设「${预设.name}」里的条目`,
    可保存: true,
    提示: '改的是本地快照，不动酒馆里的原预设；重新拉取快照会覆盖这里的修改。',
  };
  草稿.value = {
    名称: 条目.name,
    内容: 条目.content ?? '',
    启用: 条目.enabled,
    角色: 条目.role,
    位置: 条目.position,
  };
}

function 类别名(类: ReturnType<typeof entryKind>): string {
  return 类 === 'system' ? '系统提示词' : 类 === 'placeholder' ? '占位符' : '普通条目';
}

// 换对象就重新读入。用 对象标识 而不是 props.对象，避免同一对象被重新赋值时把草稿冲掉
watch(对象标识, 读入, { immediate: true });

const 显示位置 = computed(() => (props.对象 ? hasPositionField({ id: 条目id() }) : false));
const 是相对位置 = computed(() => 草稿.value?.位置?.type !== 'in_chat');

function 条目id(): string {
  const o = props.对象;
  if (!o) return '';
  if (o.类型 === 'source') return o.promptId;
  if (o.类型 === 'target') return o.uid.split('::').slice(1).join('::') || o.uid;
  return '';
}

function 保存() {
  const o = props.对象;
  const 稿 = 草稿.value;
  if (!o || !稿) return;

  const 补丁 = {
    name: 稿.名称,
    content: 稿.内容,
    enabled: 稿.启用,
    role: 稿.角色,
    position: 稿.位置,
  };

  if (o.类型 === 'target') store.更新目标条目(o.uid, 补丁);
  else if (o.类型 === 'ai') store.更新AI结果(o.id, { name: 稿.名称, content: 稿.内容 });
  else store.更新源条目(o.presetId, o.promptId, 补丁);

  toastr.success('已保存', '奇美拉·预设缝合台');
}

function 切换位置类型(相对: boolean) {
  if (!草稿.value) return;
  草稿.value.位置 = 相对 ? { type: 'relative' } : { type: 'in_chat', depth: 4, order: 100 };
}
</script>

<template>
  <div class="flex-1 min-h-0 flex flex-col">
    <div v-if="!草稿" class="p-4 text-xs text-muted leading-relaxed">
      在中栏点选任意条目开始编辑 —— 目标条目、AI 生成结果、源预设里的条目都可以。
    </div>

    <template v-else>
      <!-- 头部信息 -->
      <div class="px-2.5 py-1.5 shrink-0 flex items-center gap-2 text-xs border-b border-line flex-wrap">
        <span class="px-1.5 py-0.5 rounded bg-surface2 text-muted shrink-0">{{ 元信息.类别 }}</span>
        <span class="text-muted truncate">{{ 元信息.来源 }}</span>
        <span class="ml-auto flex items-center gap-1 shrink-0">
          <span class="text-muted text-[10px]">{{ 元信息.可保存 ? '未保存的改动需点保存' : '' }}</span>
        </span>
      </div>

      <p v-if="元信息.提示" class="px-2.5 py-1 text-[10px] text-warn shrink-0 border-b border-line/40">
        <i class="fa-solid fa-circle-info mr-1" />{{ 元信息.提示 }}
      </p>

      <!-- 变量冲突的裁决浮条：只在从树上的冲突值行点进来时出现 -->
      <div
        v-if="待采用"
        class="px-2.5 py-1.5 shrink-0 border-b border-warn/40 bg-warn/10 flex items-center gap-2 text-[11px]"
      >
        <i class="fa-solid fa-triangle-exclamation text-warn shrink-0" />
        <span class="flex-1 min-w-0">
          「{{ 待采用.变量名 }}」各来源的值不一致，采用这条的值：
          <span class="font-medium">{{ 待采用.值 || '（空）' }}</span>
        </span>
        <button
          class="shrink-0 px-2 py-0.5 rounded bg-accent text-accent-text font-medium"
          @click="emit('采用值')"
        >
          采用
        </button>
      </div>

      <!-- 编辑区：独立滚动 -->
      <div class="flex-1 min-h-0 overflow-y-auto p-2 space-y-2 text-xs">
        <label class="block">
          <span class="text-muted">名称</span>
          <input v-model="草稿.名称" class="w-full mt-0.5" />
        </label>

        <label class="block">
          <span class="text-muted">内容</span>
          <textarea v-model="草稿.内容" rows="14" class="w-full mt-0.5 text-[11px] font-mono leading-relaxed" />
        </label>

        <div class="flex items-center gap-4">
          <label class="flex items-center gap-1.5 cursor-pointer">
            <input v-model="草稿.启用" type="checkbox" />启用
          </label>
          <label class="flex items-center gap-1.5">
            <span class="text-muted">角色</span>
            <select v-model="草稿.角色">
              <option value="system">system</option>
              <option value="user">user</option>
              <option value="assistant">assistant</option>
            </select>
          </label>
        </div>

        <details v-if="显示位置" class="border border-line rounded-md">
          <summary class="px-2 py-1 cursor-pointer select-none text-muted">高级 · 插入方式</summary>
          <div class="p-2 space-y-2 border-t border-line">
            <label class="flex items-center gap-2 cursor-pointer">
              <input type="radio" :checked="是相对位置" @change="切换位置类型(true)" /> 相对位置
            </label>
            <label class="flex items-center gap-2 cursor-pointer">
              <input type="radio" :checked="!是相对位置" @change="切换位置类型(false)" /> 插入到聊天深度
            </label>
            <div v-if="!是相对位置" class="flex items-center gap-3 pl-5">
              <label class="flex items-center gap-1">
                深度
                <input
                  :value="(草稿.位置 as any)?.depth"
                  type="number"
                  min="0"
                  class="w-16"
                  @input="(草稿.位置 as any).depth = Number(($event.target as HTMLInputElement).value)"
                />
              </label>
              <label class="flex items-center gap-1">
                顺序
                <input
                  :value="(草稿.位置 as any)?.order"
                  type="number"
                  class="w-20"
                  @input="(草稿.位置 as any).order = Number(($event.target as HTMLInputElement).value)"
                />
              </label>
            </div>
          </div>
        </details>

        <div class="flex gap-2 pt-0.5">
          <button class="px-3 py-1 rounded-md bg-accent text-accent-text font-medium" @click="保存">保存</button>
          <button class="px-3 py-1 rounded-md border border-line hover:border-line-strong" @click="读入">
            放弃改动
          </button>
        </div>
      </div>
    </template>
  </div>
</template>
