<script setup lang="ts">
/**
 * 手机版「界面设置」底部抽屉。
 *
 * 由悬浮球目录进入。所有改动即时生效：本组件只负责 emit 一份完整的新外观，
 * 由 App.vue 写入存储并套用 CSS 变量 —— 单一数据源，避免「预览和存档不一致」。
 */
import { 默认外观, type 外观设置 } from '../界面设置.ts';

const props = defineProps<{
  外观: 外观设置;
  主题: 'dark' | 'light';
}>();

const emit = defineEmits<{
  更新: [外观: 外观设置];
  设为主题: [主题: 'dark' | 'light'];
  关闭: [];
}>();

/** 合并式更新：每次只改一个字段，其余保持当前值 */
function 改(补丁: Partial<外观设置>) {
  emit('更新', { ...props.外观, ...补丁 });
}

const 高度选项 = [100, 90, 80, 70];
const 边距选项 = [12, 16, 20];
const 字号选项 = [0.85, 1, 1.15, 1.3];
const 球大小选项 = [40, 44, 52, 60];

const 主色候选: { 值: string | null; 名: string }[] = [
  { 值: null, 名: '跟随主题' },
  { 值: '#38bdf8', 名: '天蓝' },
  { 值: '#34d399', 名: '翠绿' },
  { 值: '#fbbf24', 名: '琥珀' },
  { 值: '#fb7185', 名: '玫红' },
  { 值: '#a78bfa', 名: '紫罗兰' },
];

function 取数字(event: Event): number {
  return Number((event.target as HTMLInputElement).value);
}

const 选项样式 = (选中: boolean) =>
  选中
    ? 'bg-accent text-accent-text border-accent font-medium'
    : 'border-line text-muted hover:border-accent hover:text-accent';
</script>

<template>
  <div class="fixed inset-0 z-[60] flex items-end" @click.self="emit('关闭')">
    <div class="absolute inset-0 bg-black/50" @click="emit('关闭')" />

    <div
      class="relative w-full max-h-[88%] overflow-y-auto glass-strong rounded-t-2xl px-4 pt-3"
      style="padding-bottom: calc(20px + var(--面板安全区下, 0px))"
    >
      <!-- 顶部把手 + 标题 -->
      <div class="flex items-center justify-between pb-2">
        <div class="text-[13px] font-semibold flex items-center gap-1.5">
          <i class="fa-solid fa-sliders text-accent" />
          界面设置
        </div>
        <button
          class="w-9 h-9 -mr-1 rounded-md flex items-center justify-center hover:bg-surface2 touch-manipulation"
          title="关闭设置"
          @click="emit('关闭')"
        >
          <i class="fa-solid fa-xmark text-xl" />
        </button>
      </div>

      <!-- ============ 尺寸与留白 ============ -->
      <div class="space-y-3 pt-2 border-t border-line">
        <div class="pt-2 text-[11px] text-muted">尺寸与留白</div>

        <div>
          <div class="text-[12px] mb-1.5">界面高度</div>
          <div class="grid grid-cols-4 gap-1">
            <button
              v-for="n in 高度选项"
              :key="n"
              class="h-9 rounded-lg text-[12px] border transition-colors touch-manipulation"
              :class="选项样式(外观.界面高度 === n)"
              @click="改({ 界面高度: n })"
            >
              {{ n }}%
            </button>
          </div>
          <div class="text-[10px] text-muted mt-1">
            小于 100% 时下方会露出酒馆界面，也可让底部操作条不再被系统栏挡住。
          </div>
        </div>

        <div>
          <div class="text-[12px] mb-1.5">左右边距</div>
          <div class="grid grid-cols-3 gap-1">
            <button
              v-for="n in 边距选项"
              :key="n"
              class="h-9 rounded-lg text-[12px] border transition-colors touch-manipulation"
              :class="选项样式(外观.左右边距 === n)"
              @click="改({ 左右边距: n })"
            >
              {{ n }}px
            </button>
          </div>
        </div>

        <div class="flex items-center gap-3">
          <span class="text-[12px] w-16 shrink-0">顶部留白</span>
          <input
            class="ps-range flex-1"
            type="range"
            min="0"
            max="64"
            step="2"
            :value="外观.顶部留白"
            @input="改({ 顶部留白: 取数字($event) })"
          />
          <span class="w-11 text-right text-[11px] text-muted tabular-nums">{{ 外观.顶部留白 }}px</span>
        </div>

        <div class="flex items-center gap-3">
          <span class="text-[12px] w-16 shrink-0">底部留白</span>
          <input
            class="ps-range flex-1"
            type="range"
            min="0"
            max="64"
            step="2"
            :value="外观.底部留白"
            @input="改({ 底部留白: 取数字($event) })"
          />
          <span class="w-11 text-right text-[11px] text-muted tabular-nums">{{ 外观.底部留白 }}px</span>
        </div>

        <div>
          <div class="text-[12px] mb-1.5">字号缩放</div>
          <div class="grid grid-cols-4 gap-1">
            <button
              v-for="n in 字号选项"
              :key="n"
              class="h-9 rounded-lg text-[12px] border transition-colors touch-manipulation"
              :class="选项样式(外观.字号缩放 === n)"
              @click="改({ 字号缩放: n })"
            >
              {{ Math.round(n * 100) }}%
            </button>
          </div>
        </div>

        <div>
          <div class="text-[12px] mb-1.5">悬浮球大小</div>
          <div class="grid grid-cols-4 gap-1">
            <button
              v-for="n in 球大小选项"
              :key="n"
              class="h-9 rounded-lg text-[12px] border transition-colors touch-manipulation"
              :class="选项样式(外观.悬浮球大小 === n)"
              @click="改({ 悬浮球大小: n })"
            >
              {{ n }}px
            </button>
          </div>
        </div>
      </div>

      <!-- ============ 配色 ============ -->
      <div class="space-y-3 pt-3 mt-3 border-t border-line">
        <div class="text-[11px] text-muted">配色</div>

        <div>
          <div class="text-[12px] mb-1.5">日夜主题</div>
          <div class="grid grid-cols-2 gap-1">
            <button
              class="h-9 rounded-lg text-[12px] border transition-colors touch-manipulation flex items-center justify-center gap-1.5"
              :class="选项样式(主题 === 'dark')"
              @click="emit('设为主题', 'dark')"
            >
              <i class="fa-solid fa-moon" />夜间
            </button>
            <button
              class="h-9 rounded-lg text-[12px] border transition-colors touch-manipulation flex items-center justify-center gap-1.5"
              :class="选项样式(主题 === 'light')"
              @click="emit('设为主题', 'light')"
            >
              <i class="fa-solid fa-sun" />日间
            </button>
          </div>
        </div>

        <div>
          <div class="text-[12px] mb-1.5">主色</div>
          <div class="flex items-center gap-2 flex-wrap">
            <button
              v-for="项 in 主色候选"
              :key="项.名"
              class="w-9 h-9 rounded-full border-2 flex items-center justify-center transition-transform active:scale-95 touch-manipulation"
              :class="外观.主色 === 项.值 ? 'border-accent' : 'border-line'"
              :style="
                项.值
                  ? { background: 项.值 }
                  : { background: 'linear-gradient(135deg, #38bdf8 0 50%, #fbbf24 50% 100%)' }
              "
              :title="项.名"
              @click="改({ 主色: 项.值 })"
            >
              <i
                v-if="外观.主色 === 项.值"
                class="fa-solid fa-check text-[11px]"
                :style="{ color: 项.值 ? '#ffffff' : '#0b1220' }"
              />
            </button>

            <!-- 自定义取色器：与色板同尺寸，选中后走「自定义主色」 -->
            <input
              class="ps-color"
              type="color"
              title="自定义主色"
              :value="外观.主色 ?? '#38bdf8'"
              @input="改({ 主色: ($event.target as HTMLInputElement).value })"
            />
          </div>
          <div class="text-[10px] text-muted mt-1">
            「跟随主题」会随日夜主题自动换色；选具体颜色后固定不变。
          </div>
        </div>
      </div>

      <button
        class="w-full h-10 mt-4 rounded-lg border border-line text-[12px] text-muted transition-colors hover:text-danger hover:border-danger touch-manipulation"
        @click="改(默认外观)"
      >
        <i class="fa-solid fa-rotate-left mr-1" />恢复默认设置
      </button>
    </div>
  </div>
</template>
