/**
 * 手机版的界面偏好（悬浮球位置 + 外观设置）。
 *
 * 为什么另开一个存储键、不塞进共用工作区数据：
 * 工作是 `version: 3` 的结构，且【桌面版与手机版共用同一份】。
 * 为一个手机版的界面细节去升数据结构版本、还要写旧数据的兼容读，代价不成比例；
 * 而桌面版是三栏布局，根本不需要知道悬浮球在哪、面板多高。
 * 分开存，两边互不牵连，桌面版完全感知不到。
 */
import { 读取设置键, 写入设置键 } from '../预设缝合助手/core/tavern.ts';

const 界面设置键 = '预设缝合助手-手机版界面';

/**
 * 外观设置变化时派发的窗口事件。
 *
 * 面板（Vue）跑在酒馆主页面的 JS 作用域里，而 iframe 的高度由 index.ts 控制。
 * 两者共享同一个 window，所以用事件把「高度变了」通知过去，
 * 不需要为了一个尺寸再搭一套 postMessage / provide 通道。
 */
export const 界面变更事件 = '预设缝合助手-手机版-界面变更';

/** 悬浮球停靠在哪一侧 */
export type 吸附边 = 'left' | 'right';

export type 悬浮球位置 = {
  /** 吸附到哪一边（松手后自动吸附最近的一侧） */
  边: 吸附边;
  /** 球顶边距离视口上沿的像素。纵向完全自由，不做吸附 */
  纵向: number;
};

/**
 * 手机版外观。
 *
 * 所有数值都做钳制再使用：用户能直接编辑 settings.json，
 * 存档也可能来自旧版本，宁可退回默认值也不能让界面尺寸失控。
 */
export type 外观设置 = {
  /** 面板占可见视口高度的百分比。100 = 全屏；小于 100 时下方露出酒馆界面 */
  界面高度: number;
  /** 页面左右内边距（px） */
  左右边距: number;
  /** 顶部额外留白（px）。0 = 顶栏紧贴屏幕可见区上沿 */
  顶部留白: number;
  /** 底部额外留白（px）。在安全区之外再抬高，避免被系统手势条挡住 */
  底部留白: number;
  /** 整体字号缩放系数（0.85 ~ 1.3） */
  字号缩放: number;
  /** 悬浮球直径（px） */
  悬浮球大小: number;
  /** 自定义主色（#rrggbb）。null = 跟随日夜主题的默认主色 */
  主色: string | null;
};

export const 默认外观: 外观设置 = {
  界面高度: 100,
  左右边距: 16,
  // 顶部的空白横条就是旧版无条件叠加的安全区留白；默认改为 0
  顶部留白: 0,
  // 底部默认再抬 10px，避开手机系统手势条 / 浏览器底栏
  底部留白: 10,
  字号缩放: 1,
  悬浮球大小: 44,
  主色: null,
};

export type 手机版界面 = {
  /** 没存过时为 null，由组件按「左下角」算默认值 */
  悬浮球: 悬浮球位置 | null;
  外观: 外观设置;
};

const 默认界面: 手机版界面 = { 悬浮球: null, 外观: { ...默认外观 } };

/** 读取界面偏好。没存过或存档损坏都退回默认值 */
export function 读取界面设置(): 手机版界面 {
  const 存档 = 读取设置键<Partial<手机版界面>>(界面设置键);
  if (!存档 || typeof 存档 !== 'object') return { 悬浮球: null, 外观: { ...默认外观 } };
  return { 悬浮球: 合法位置(存档.悬浮球), 外观: 合法外观(存档.外观) };
}

/**
 * 写入界面偏好（增量合并）。
 *
 * 【必须合并，不能整体覆盖】：悬浮球位置与外观设置分属两个组件写入，
 * 整体覆盖会让「拖了一下球」把用户刚调好的配色/尺寸静默清空。
 */
export function 写入界面设置(补丁: Partial<手机版界面>): void {
  const 现 = 读取界面设置();
  const 新: 手机版界面 = { ...现 };
  if (补丁.悬浮球 !== undefined) 新.悬浮球 = 补丁.悬浮球;
  if (补丁.外观 !== undefined) 新.外观 = 补丁.外观;
  写入设置键(界面设置键, 新);
}

/**
 * 校验存档里的位置。
 * 存档可能来自旧版本、也可能被手动改坏（用户能直接编辑 settings.json），
 * 宁可退回默认位置，也不能让球停在屏幕外找不回来。
 * 越界只做类型/存在性检查，具体范围由组件按当前视口钳制 —— 窗口尺寸随时会变。
 */
function 合法位置(值: unknown): 悬浮球位置 | null {
  if (!值 || typeof 值 !== 'object') return null;
  const 候选 = 值 as Partial<悬浮球位置>;
  if (候选.边 !== 'left' && 候选.边 !== 'right') return null;
  if (typeof 候选.纵向 !== 'number' || !Number.isFinite(候选.纵向)) return null;
  return { 边: 候选.边, 纵向: 候选.纵向 };
}

/** 数值字段统一钳制：类型不对 / 越界 / NaN 一律拉回合法区间 */
function 钳制数值(值: unknown, 下限: number, 上限: number, 默认: number): number {
  const 数 = typeof 值 === 'number' && Number.isFinite(值) ? 值 : 默认;
  return Math.min(上限, Math.max(下限, 数));
}

function 合法外观(值: unknown): 外观设置 {
  if (!值 || typeof 值 !== 'object') return { ...默认外观 };
  const 候选 = 值 as Partial<外观设置>;
  return {
    界面高度: 钳制数值(候选.界面高度, 60, 100, 默认外观.界面高度),
    左右边距: 钳制数值(候选.左右边距, 8, 24, 默认外观.左右边距),
    顶部留白: 钳制数值(候选.顶部留白, 0, 64, 默认外观.顶部留白),
    底部留白: 钳制数值(候选.底部留白, 0, 64, 默认外观.底部留白),
    字号缩放: 钳制数值(候选.字号缩放, 0.85, 1.3, 默认外观.字号缩放),
    悬浮球大小: 钳制数值(候选.悬浮球大小, 36, 72, 默认外观.悬浮球大小),
    主色: 合法颜色(候选.主色),
  };
}

/** 只接受 #rrggbb；其它值一律视为「跟随主题」 */
function 合法颜色(值: unknown): string | null {
  if (typeof 值 !== 'string') return null;
  return /^#[0-9a-f]{6}$/i.test(值.trim()) ? 值.trim().toLowerCase() : null;
}
