import { deepClone } from './clone.ts';
import { normalizeLegacyRegex, toLegacyRegex } from './regex.ts';
import type { LegacyRegexScript, Preset, PresetPrompt, TavernRegex } from '../types.ts';

/**
 * 酒馆原生 API 适配层。
 *
 * 本项目做成真正的酒馆扩展，不依赖酒馆助手，因此所有原本由酒馆助手提供的接口
 * 都在这里用 SillyTavern.getContext() 重新实现。
 *
 * 预设格式归一化移植自酒馆助手 4.8.10 的 src/function/preset.ts（toPreset / fromPreset），
 * 但做了一处关键简化：**settings 原样保留，不做字段映射**。
 * 理由：本插件只把骨架预设的 settings 整体搬过来再写回去，不单独改任何一个生成参数；
 * 原样保留既免去几十个字段的正反映射，又避免了酒馆助手那套映射带来的字段丢失
 * （例如 from_tavern_regex 会把 substituteRegex 硬编码成 0）。
 */

/** 本插件只针对对话补全（openai 格式）预设 */
const API_ID = 'openai';

/** 酒馆按 character_id 区分不同角色卡的提示词顺序，这个值是对话补全实际使用的 */
const PROMPT_ORDER_CHARACTER_ID = 100001;

type 任意 = Record<string, any>;

function 取上下文(): 任意 {
  const context = (SillyTavern as unknown as { getContext?: () => 任意 }).getContext?.();
  if (!context) throw new Error('无法获取酒馆上下文，请刷新页面后重试');
  return context;
}

function 预设管理器(): 任意 {
  const manager = 取上下文().getPresetManager?.(API_ID);
  if (!manager) throw new Error(`无法获取「${API_ID}」格式的预设管理器`);
  return manager;
}

/* ============ 名称与查找 ============ */

/** 酒馆里全部预设名（不含 'in_use' 这个虚拟项） */
export function getPresetNames(): string[] {
  try {
    const { preset_names } = 预设管理器().getPresetList();
    return Array.isArray(preset_names) ? [...preset_names] : Object.keys(preset_names);
  } catch (error) {
    console.error('[预设缝合助手] 读取预设列表失败', error);
    return [];
  }
}

/** 当前正在使用的预设名 */
export function getLoadedPresetName(): string {
  try {
    return 预设管理器().getSelectedPresetName() ?? '';
  } catch {
    return '';
  }
}

/** 按名字取原始预设对象（酒馆原生格式，含 prompts / prompt_order / 全部生成参数） */
function 取原始预设(name: string): 任意 | null {
  try {
    const manager = 预设管理器();
    const { presets, preset_names } = manager.getPresetList();
    const index = Array.isArray(preset_names) ? preset_names.indexOf(name) : preset_names[name];
    if (index === undefined || index === -1) return null;
    return presets[index] ?? null;
  } catch (error) {
    console.error(`[预设缝合助手] 读取预设「${name}」失败`, error);
    return null;
  }
}

/* ============ 归一化：酒馆原始 → 本插件 ============ */

function 归一化条目(原始: 任意, 顺序表: { identifier: string; enabled: boolean }[]): PresetPrompt {
  const 是占位符 = 原始.marker === true;
  const 是系统词 = 原始.system_prompt === true && !是占位符;
  const 是普通条目 = 原始.system_prompt === false && !是占位符;

  const 结果: 任意 = {
    id: 原始.identifier ?? crypto.randomUUID?.() ?? String(Math.random()),
    name: 原始.name ?? 'unnamed',
    enabled: 顺序表.find(item => item.identifier === 原始.identifier)?.enabled ?? 原始.enabled ?? true,
  };

  if (是普通条目 || 是占位符) {
    if (原始.injection_position === 1) {
      结果.position = {
        type: 'in_chat',
        depth: 原始.injection_depth ?? 4,
        order: 原始.injection_order ?? 100,
      };
    } else {
      结果.position = { type: 'relative' };
    }
  }

  结果.role = 原始.role ?? 'system';
  if (是普通条目 || 是系统词) 结果.content = 原始.content ?? '';
  if (原始.extra) 结果.extra = 原始.extra;

  return 结果 as PresetPrompt;
}

/** 把酒馆原始预设转换成本插件使用的结构 */
export function getPreset(name: string): Preset {
  const 原始 = 取原始预设(name);
  if (!原始) throw new Error(`预设「${name}」不存在`);

  const 顺序表: { identifier: string; enabled: boolean }[] =
    原始.prompt_order?.find((o: 任意) => o.character_id === PROMPT_ORDER_CHARACTER_ID)?.order ?? [];

  const 全部条目: PresetPrompt[] = (原始.prompts ?? []).map((p: 任意) => 归一化条目(p, 顺序表));

  // 酒馆的 prompts 数组顺序不等于生效顺序，生效顺序由 prompt_order 决定，
  // 所以这里按 prompt_order 重排；不在顺序表里的条目归入「未使用」。
  const 顺序id表 = 顺序表.map(o => o.identifier);
  const 已用: PresetPrompt[] = [];
  const 未用: PresetPrompt[] = [];
  for (const 条目 of 全部条目) {
    if (顺序id表.includes(条目.id)) 已用.push(条目);
    else 未用.push(条目);
  }
  已用.sort((a, b) => 顺序id表.indexOf(a.id) - 顺序id表.indexOf(b.id));

  const 正则: TavernRegex[] = (原始.extensions?.regex_scripts ?? []).map((r: 任意) =>
    r && typeof r === 'object' && 'scriptName' in r ? normalizeLegacyRegex(r as LegacyRegexScript) : r,
  );

  return {
    // settings 原样保留酒馆的全部生成参数，不做任何字段映射
    settings: deepClone(原始),
    prompts: 已用,
    prompts_unused: 未用,
    extensions: { ...(原始.extensions ?? {}), regex_scripts: 正则 },
  };
}

/* ============ 反归一化：本插件 → 酒馆原始 ============ */

function 反归一化条目(条目: PresetPrompt): 任意 {
  const 是系统词 = ['main', 'nsfw', 'jailbreak', 'enhanceDefinitions'].includes(条目.id);
  const 是占位符 = [
    'worldInfoBefore',
    'personaDescription',
    'charDescription',
    'charPersonality',
    'scenario',
    'worldInfoAfter',
    'dialogueExamples',
    'chatHistory',
  ].includes(条目.id);

  const 结果: 任意 = {
    identifier: 条目.id,
    name: 条目.name,
    enabled: 条目.enabled,
    role: 条目.role,
    system_prompt: 是系统词 || 是占位符,
    marker: 是占位符,
    forbid_overrides: false,
  };

  // 这两个占位符在酒馆里不带插入位置字段
  if ((!是系统词 || 是占位符) && !['dialogueExamples', 'chatHistory'].includes(条目.id)) {
    const 位置 = 条目.position ?? { type: 'relative' as const };
    结果.injection_position = 位置.type === 'in_chat' ? 1 : 0;
    结果.injection_depth = 位置.type === 'in_chat' ? 位置.depth : 4;
    结果.injection_order = 位置.type === 'in_chat' ? 位置.order : 100;
  }

  if (!是占位符) 结果.content = 条目.content ?? '';
  if (条目.extra) 结果.extra = 条目.extra;

  return 结果;
}

/** 把本插件结构转回酒馆原始预设 */
function 转回原始预设(preset: Preset): 任意 {
  const 全部 = [...preset.prompts, ...(preset.prompts_unused ?? [])];

  // 防止系统词/占位符重复 —— 酒馆不接受重复，写进去会导致预设损坏
  const 已见 = new Set<string>();
  for (const 条目 of 全部) {
    const 是普通条目 = !['main', 'nsfw', 'jailbreak', 'enhanceDefinitions'].includes(条目.id) &&
      ![
        'worldInfoBefore', 'personaDescription', 'charDescription', 'charPersonality',
        'scenario', 'worldInfoAfter', 'dialogueExamples', 'chatHistory',
      ].includes(条目.id);
    if (已见.has(条目.id)) {
      if (!是普通条目) throw new Error(`预设中存在重复的系统提示词或占位符「${条目.id}」，无法写入`);
    }
    已见.add(条目.id);
  }

  const 原始 = deepClone(preset.settings ?? {}) as 任意;
  原始.prompts = 全部.map(反归一化条目);
  原始.prompt_order = [
    {
      character_id: PROMPT_ORDER_CHARACTER_ID,
      order: preset.prompts.map(p => ({ identifier: p.id, enabled: p.enabled })),
    },
  ];
  原始.extensions = {
    ...(原始.extensions ?? {}),
    ...(preset.extensions ?? {}),
    regex_scripts: (preset.extensions?.regex_scripts ?? []).map((r: TavernRegex) => toLegacyRegex(r)),
  };

  return 原始;
}

/* ============ 写入与切换 ============ */

/**
 * 新建或覆盖一个预设。
 * @returns true 表示新建，false 表示覆盖
 */
export async function createOrReplacePreset(name: string, preset: Preset): Promise<boolean> {
  const manager = 预设管理器();
  const 原始 = 转回原始预设(preset);
  const 已存在 = getPresetNames().includes(name);

  if (!已存在) {
    const { presets, preset_names } = manager.getPresetList();
    if (Array.isArray(preset_names)) {
      presets.push(原始);
      preset_names.push(name);
    } else {
      presets.push(原始);
      preset_names[name] = presets.length - 1;
      // 同步下拉框选项，否则新预设不会出现在列表里
      manager.select?.append?.(
        $('<option></option>', { value: presets.length - 1, text: name, selected: false }),
      );
    }
  } else {
    const { presets, preset_names } = manager.getPresetList();
    const index = Array.isArray(preset_names) ? preset_names.indexOf(name) : preset_names[name];
    presets[index] = 原始;
  }

  // 写盘。skipUpdate 表示不刷新预设列表 UI（我们自己处理）
  await manager.savePreset(name, 原始, { skipUpdate: 已存在 });
  if (已存在) manager.updateList?.(name, 原始);

  return !已存在;
}

/** 切换酒馆正在使用的预设 */
export function loadPreset(name: string): boolean {
  try {
    const manager = 预设管理器();
    const value = manager.findPreset(name);
    if (value === undefined || value === null || value === '') return false;
    manager.selectPreset(value);
    return true;
  } catch (error) {
    console.warn(`[预设缝合助手] 切换预设「${name}」失败`, error);
    return false;
  }
}

/* ============ AI 调用 ============ */

/**
 * 调一次酒馆的原生 generateRaw。
 *
 * 注意签名与酒馆助手的不同：酒馆原生接收 systemPrompt + prompt（字符串或消息数组），
 * 不接受 ordered_prompts。用 systemPrompt 分开传可以让主模型区分指令与素材。
 *
 * 另注意 prompt 内容会经过 substituteParams，因此 {{user}} 之类的酒馆宏会被替换成实际值。
 * 对「判断条目相关性」影响很小，但改写条目时若条目里含 {{user}}，AI 看到的是替换后的文本。
 */
export async function generateRawText(systemPrompt: string, userContent: string): Promise<string> {
  const context = 取上下文();
  if (typeof context.generateRaw !== 'function') {
    throw new Error('当前酒馆版本不支持 generateRaw，请升级 SillyTavern');
  }

  const result = await context.generateRaw({
    systemPrompt,
    prompt: [{ role: 'user', content: userContent }],
    responseLength: 4096,
  });

  return typeof result === 'string' ? result : String(result ?? '');
}

/**
 * 中止当前正在进行的 AI 生成。
 *
 * 酒馆原生的 generateRaw 内部监听了 GENERATION_STOPPED 事件，
 * 所以调用 context.stopGeneration() 就能把它中断。
 * 界面上还需要配合一个「应中止」标志位，才能停掉分批循环 —— 否则只是中断了当前这一批，
 * 下一批又开始了。
 */
export function 中止生成(): void {
  try {
    const context = 取上下文();
    if (typeof context.stopGeneration === 'function') {
      context.stopGeneration();
    } else if (typeof context.stopAllGeneration === 'function') {
      context.stopAllGeneration();
    }
  } catch (error) {
    console.warn('[预设缝合助手] 中止生成失败', error);
  }
}

/* ============ 持久化 ============ */

const 扩展设置键 = '预设缝合助手';

/**
 * 按 key 读写 extension_settings 里的任意一条记录。
 *
 * 抽出来是为了让「工作区数据」和「界面偏好」各占一个 key、互不牵连：
 * 结构是 version:3 且【桌面版与手机版共用同一份】，
 * 为一个手机版的界面小设置去升数据结构版本、还要写兼容读，代价不成比例。
 */
export function 读取设置键<T = 任意>(键: string): T | null {
  try {
    const settings = 取上下文().extensionSettings as 任意;
    return (settings?.[键] as T) ?? null;
  } catch (error) {
    console.error(`[预设缝合助手] 读取设置「${键}」失败`, error);
    return null;
  }
}

/** 写入 extension_settings 里的任意一条记录 */
export function 写入设置键(键: string, 值: unknown): void {
  try {
    const context = 取上下文();
    const settings = context.extensionSettings as 任意;
    settings[键] = 值;
    context.saveSettingsDebounced?.();
  } catch (error) {
    console.error(`[预设缝合助手] 写入设置「${键}」失败`, error);
  }
}

/** 读取本扩展的持久化数据 */
export function 读取扩展数据(): 任意 | null {
  return 读取设置键(扩展设置键);
}

/** 写入本扩展的持久化数据 */
export function 写入扩展数据(data: 任意): void {
  写入设置键(扩展设置键, data);
}

/* ============ 预设正则白名单 ============ */

/**
 * 启用该预设的正则白名单。
 *
 * 酒馆的预设正则有白名单机制（scripts/extensions/regex/engine.js 的 isPresetScriptsAllowed），
 * 只有 extension_settings.preset_allowed_regex[apiId] 里含该预设名时它的正则才生效。
 * 新建的预设默认不在白名单里 —— 不补的话用户会发现「正则缝进去了但不生效」。
 */
export function ensurePresetRegexAllowed(presetName: string): boolean {
  try {
    const context = 取上下文();
    const apiId = context.getPresetManager?.()?.apiId ?? API_ID;
    const settings = context.extensionSettings as 任意;
    settings.preset_allowed_regex ??= {};
    settings.preset_allowed_regex[apiId] ??= [];
    if (!settings.preset_allowed_regex[apiId].includes(presetName)) {
      settings.preset_allowed_regex[apiId].push(presetName);
      context.saveSettingsDebounced?.();
    }
    return true;
  } catch (error) {
    console.warn('[预设缝合助手] 启用预设正则白名单失败，请手动在酒馆正则设置中勾选', error);
    return false;
  }
}

/** 判断某预设是否尚未在正则白名单中 */
export function 需要补白名单(presetName: string): boolean {
  try {
    const context = 取上下文();
    const apiId = context.getPresetManager?.()?.apiId ?? API_ID;
    const allowed = (context.extensionSettings as 任意)?.preset_allowed_regex?.[apiId];
    return !Array.isArray(allowed) || !allowed.includes(presetName);
  } catch {
    return false;
  }
}

/** 供类型参考：本文件用到的酒馆正则原始格式 */
export type { LegacyRegexScript };
