<script setup lang="ts">
import { computed } from 'vue';
import { 节点已勾选, type 变量图, type 变量状态 } from '../core/variables.ts';

const props = defineProps<{
  图: 变量图;
  注入: Record<string, boolean>;
  选中id: string | null;
  /** 顶部统计条选中的状态筛选；null = 不过滤 */
  筛选?: 变量状态 | null;
}>();

const emit = defineEmits<{
  选中: [id: string];
  切换注入: [id: string];
  /** 只给悬空变量用：它没有来源，必须有个地方补初值 */
  裁决: [变量名: string, 值: string];
}>();

/*
 * 布局：所有行**等高**，纵向依次排列。
 *
 * `buildVarGraph` 保证了一个声明行后面紧跟它的全部值行，所以只需要按下标取 y。
 * 等高是关键 —— 一旦行高随内容变，就要算累计偏移，而且连线端点容易算错。
 * 卡片里放不下的内容一律截断，完整内容点开看。
 */
const 行高 = 56;
const 行距 = 8;
const 内边距 = 20;
const 左列宽 = 190;
const 右列宽 = 340;
/** 两列的间距。原来 80 看着声明和值离得太开，线也拖得长 */
const 列距 = 36;

const 左列x = 内边距;
const 右列x = 内边距 + 左列宽 + 列距;

function 行y(下标: number): number {
  return 内边距 + 下标 * (行高 + 行距);
}

/** 声明行 id → 它后面跟着几个值行 */
const 值行数 = computed(() => {
  const 表 = new Map<string, number>();
  const 行 = props.图.行;
  for (let i = 0; i < 行.length; i++) {
    if (行[i].类型 !== 'decl') continue;
    let k = 0;
    while (i + 1 + k < 行.length && 行[i + 1 + k].类型 === 'value') k++;
    表.set(行[i].id, k);
  }
  return 表;
});

/**
 * 声明行的纵向位置：垂直居中于它那组值行，而不是钉在第一行。
 *
 * 钉在第一行时，一个有 3 条值行的变量会让声明卡显得「往上飘」，
 * 和它的值行对不上。居中之后单个值行的变量位置不变（正好落在同一行），
 * 多值行的变量则一眼能看出「这一块是它的」。
 *
 * 居中不会造成连线交叉：每个变量占的纵向区间是独立的，居中只在该区间内部移动。
 */
function 声明y(下标: number, id: string): number {
  const k = 值行数.value.get(id) ?? 0;
  const 块顶 = 行y(下标);
  const 块底 = 行y(下标 + k);
  return (块顶 + 块底 + 行高) / 2 - 行高 / 2;
}

const 画布宽 = computed(() => 右列x + 右列宽 + 内边距);
const 画布高 = computed(() => 内边距 * 2 + props.图.行.length * (行高 + 行距));

/*
 * 动态尺寸一律走 computed 返回对象或字符串。
 * 模板里直接写含 ref 的模板字符串，一旦解包出问题就会生成 "[object Object]px"
 * 这种非法 CSS，整条声明被浏览器丢弃、布局塌掉 —— v1 在 VariableTable.vue 踩过这个坑。
 */
const 画布样式 = computed(() => ({ width: `${画布宽.value}px`, height: `${画布高.value}px` }));
const svg视框 = computed(() => `0 0 ${画布宽.value} ${画布高.value}`);

function 行样式(x: number, y: number, 宽: number) {
  return { left: `${x}px`, top: `${y}px`, width: `${宽}px`, height: `${行高}px` };
}

const 行索引 = computed(() => new Map(props.图.行.map((n, i) => [n.id, i])));

/**
 * 连线：声明卡片右边缘 → 值卡片左边缘。
 *
 * 因为值行紧跟在它的声明行之后，同一变量的线只会向下散开、绝不跨越别的变量，
 * 所以这里不需要任何避让算法，画出来天然不交叉。
 */
const 连线路径 = computed(() =>
  props.图.连线
    .map(({ from, to }) => {
      const i = 行索引.value.get(from);
      const j = 行索引.value.get(to);
      if (i === undefined || j === undefined) return '';
      // 声明端取的是它居中后的位置，不是它所在那一行的位置
      const y1 = 声明y(i, from) + 行高 / 2;
      const y2 = 行y(j) + 行高 / 2;
      const x1 = 左列x + 左列宽;
      const x2 = 右列x;
      const 控制 = 列距 / 2.4;
      return `M ${x1} ${y1} C ${x1 + 控制} ${y1}, ${x2 - 控制} ${y2}, ${x2} ${y2}`;
    })
    .filter(Boolean),
);

const 状态说明: Record<string, string> = {
  conflict: '初值有分歧，点值行可以看到各来源的完整内容再决定用哪个',
  dangling: '被引用但没有定义，在左边补一个初值',
  unused: '定义了但没有条目引用',
  ok: '正常',
};

/**
 * 声明行只有名字，状态用颜色表达而不是徽章 ——
 * 徽章会让「一条声明」看起来像个带按钮的控件，而它本来就只是一个名字。
 * 具体含义放 tooltip 里，不占版面。
 */
const 名字颜色: Record<string, string> = {
  conflict: 'text-warn',
  dangling: 'text-danger',
  unused: 'text-muted',
  ok: '',
};

/* 预览行取的是条目正文的首个非空行，由 buildVarGraph 预先算好放在 预览 字段里 */

/**
 * 当前筛选下应该「变淡」的节点 id 集合。
 *
 * 变淡而不是隐藏：删掉节点会让连线断掉、整张图重新排版，用户反而看不清结构。
 * 值行的规则是「它连着的声明行不匹配」才变淡 —— 变量的状态由声明行表达。
 */
const 变淡节点 = computed(() => {
  const 集 = new Set<string>();
  if (!props.筛选) return 集;
  const 声明状态 = new Map(props.图.行.filter(n => n.类型 === 'decl').map(n => [n.id, n.状态]));
  for (const n of props.图.行) {
    if (n.类型 === 'decl') {
      if (n.状态 !== props.筛选) 集.add(n.id);
      continue;
    }
    const 父id = props.图.连线.find(l => l.to === n.id)?.from;
    if (父id && 声明状态.get(父id) !== props.筛选) 集.add(n.id);
  }
  return 集;
});
</script>

<template>
  <div class="flex-1 min-h-0 overflow-auto">
    <div v-if="图.行.length === 0" class="p-3 text-xs text-muted leading-relaxed">
      还没有可画的变量。先在「条目」轨把带变量的条目缝进目标，或在左栏导入更多预设。
      变量形如 <code class="text-accent">setvar::名字::值</code>，但要写成双花括号宏形式。
    </div>

    <div v-else class="relative" :style="画布样式">
      <!-- 连线层：不接鼠标事件，否则会挡住下方卡片的点击 -->
      <svg
        class="absolute inset-0 pointer-events-none text-line-strong"
        :viewBox="svg视框"
        :width="画布宽"
        :height="画布高"
      >
        <path
          v-for="(d, i) in 连线路径"
          :key="i"
          :d="d"
          fill="none"
          stroke="currentColor"
          stroke-width="1.5"
        />
      </svg>

      <template v-for="(n, i) in 图.行" :key="n.id">
        <!-- ============ 声明行：一个变量一条，就是一个名字 ============ -->
        <div
          v-if="n.类型 === 'decl'"
          class="absolute rounded-lg border cursor-pointer transition-colors overflow-hidden"
          :class="[
            选中id === n.id ? 'border-accent bg-accent-soft/25' : 'border-line bg-surface hover:border-line-strong',
            { 'opacity-25': 变淡节点.has(n.id) },
          ]"
          :style="行样式(左列x, 声明y(i, n.id), 左列宽)"
          :title="`${n.变量名} —— ${状态说明[n.状态 ?? 'ok']}`"
          @click="emit('选中', n.id)"
        >
          <div class="h-full flex items-center px-2.5">
            <!--
              悬空变量没有任何来源，所以它没有值行；不给一个输入框就永远没法赋值。
              这是唯一带控件的声明行，其余声明行就是一个纯粹的名字。
            -->
            <input
              v-if="n.状态 === 'dangling'"
              class="w-full text-[11px] py-0.5"
              :value="n.值"
              placeholder="补初值…"
              @click.stop
              @change="emit('裁决', n.变量名, ($event.target as HTMLInputElement).value)"
            />
            <span v-else class="truncate text-[12px] font-medium" :class="名字颜色[n.状态 ?? 'ok']">
              {{ n.变量名 }}
            </span>
          </div>
        </div>

        <!-- ============ 值行：某个来源给这个变量的赋值，只展示首行 ============ -->
        <div
          v-else
          class="absolute rounded-lg border cursor-pointer transition-colors overflow-hidden"
          :class="[
            选中id === n.id ? 'border-accent bg-accent-soft/25' : 'border-line bg-surface2/60 hover:border-line-strong',
            { 'opacity-25': 变淡节点.has(n.id) },
          ]"
          :style="行样式(右列x, 行y(i), 右列宽)"
          :title="`${n.条目名}\n来自预设：${n.预设名}\n变量值：${n.值 || '(空)'}`"
          @click="emit('选中', n.id)"
        >
          <div class="h-full flex flex-col justify-center gap-0.5 px-2 pr-7">
            <!-- 条目名不加预设名前缀：预设名可以长到 `（开可选）【MoM】象牙塔 2.0.0 Ver @电波系（260117）` -->
            <div class="text-[11px] truncate">{{ n.条目名 }}</div>
            <div class="text-[10px] text-muted truncate">{{ n.预览 }}</div>
          </div>

          <div class="absolute right-1.5 top-1/2 -translate-y-1/2">
            <input
              type="checkbox"
              class="cursor-pointer"
              :checked="节点已勾选(注入, n.id)"
              :title="节点已勾选(注入, n.id) ? '已选：这条赋值会写入目标预设' : '未选：不写入目标预设'"
              @click.stop
              @change="emit('切换注入', n.id)"
            />
          </div>
        </div>
      </template>
    </div>
  </div>
</template>
